/// <summary>
/// 冒烟测试：验证测试工程本身的前提成立——
/// MonoGame 数学类型、Arch World、行为模组程序集均可在无图形设备、无 FMOD 的环境下使用
/// </summary>
public class SmokeTests
{
    [Fact]
    public void MonoGame 数学类型可无头使用()
    {
        var v = Vector2.One * 2 + new Vector2(1, 2);
        Assert.Equal(new Vector2(3, 4), v);

        var gameTime = new GameTime(TimeSpan.Zero, TimeSpan.FromSeconds(1.0 / 60));
        Assert.Equal(TimeSpan.FromSeconds(1.0 / 60), gameTime.ElapsedGameTime);
    }

    [Fact]
    public void Arch_World_可无头创建并挂载组件()
    {
        var world = World.Create();
        var entity = world.Create(
            new Sprite(), // Texture 留空，纯数据组件不依赖 GPU
            new AbsoluteTransform(new Vector3(1, 2, 3), Quaternion.Identity)
        );

        Assert.True(entity.Has<Sprite>());
        Assert.Null(entity.Get<Sprite>().Texture);
        Assert.Equal(new Vector3(1, 2, 3), entity.Get<AbsoluteTransform>().Translation);

        World.Destroy(world);
    }

    [Fact]
    public void 行为模组程序集可无头反射()
    {
        var schemas = typeof(TeamDeclaration)
            .Assembly.GetExportedTypes()
            .Where(t => t.GetInterfaces().Contains(typeof(IDeclaration)))
            .Select(t => t.GetCustomAttributes(typeof(SchemaNameAttribute), false))
            .Where(a => a.Length > 0)
            .Count();

        Assert.True(schemas >= 11, $"预期至少 11 个声明模式，实际 {schemas}");
    }
}

