using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using Microsoft.Extensions.Configuration;
using Nine.Assets.Serialization;
using OpenSolarMax.Game.Modding.Declaration;
using OpenSolarMax.Game.Utils;
using OpenSolarMax.Mods.S2.Declarations;

namespace OpenSolarMax.Tests.Data;

/// <summary>
/// 关卡 JSON 文件的骨架结构，与 Game 内部 LevelLoader.JsonLevel 一比一对应
/// </summary>
internal class JsonLevel
{
    public List<string> Includes { get; set; } = [];

    public Dictionary<string, JsonElement> Templates { get; set; } = [];

    public JsonElement[] Entities { get; set; } = [];

    public JsonElement? Configs { get; set; }
}

/// <summary>
/// 在测试内复刻 LevelLoader + DeclarationStatementJsonConverter 的解析流程，
/// 对关卡文件做结构、类型与引用完整性校验。
/// 复刻原因：LevelLoader 与 DeclarationStatementJsonConverter 是 internal，
/// 且本次任务不允许改动产品代码。
/// </summary>
public static class LevelFileValidator
{
    private static readonly JsonSerializerOptions BasicOptions = new()
    {
        PropertyNameCaseInsensitive = true,
        IncludeFields = true,
    };

    private static readonly JsonSerializerOptions StatementOptions = CreateStatementOptions();

    private static JsonSerializerOptions CreateStatementOptions()
    {
        var options = new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true,
            IncludeFields = true,
        };
        // 与 LevelLoader.ParseAndMerge 使用同一组转换器
        options.Converters.Add(new JsonStringEnumConverter());
        options.Converters.Add(new Vector2JsonConverter());
        options.Converters.Add(new ColorJsonConverter());
        options.Converters.Add(new BlendStateJsonConverter());
        options.Converters.Add(new OneOfJsonConverterFactory());
        return options;
    }

    /// <summary>
    /// 复刻 BehaviorMod.FindDeclarationTypes：从行为模组程序集反射出模式名到声明类型的映射
    /// </summary>
    private static Dictionary<string, Type> FindSchemaTypes() =>
        typeof(TeamDeclaration)
            .Assembly.GetExportedTypes()
            .Where(t => t.GetInterfaces().Contains(typeof(IDeclaration)))
            .ToDictionary(t => t.GetCustomAttribute<SchemaNameAttribute>()!.Name);

    /// <summary>
    /// 校验一个关卡文件（含其递归 includes）
    /// </summary>
    public static void Validate(string levelPath)
    {
        var schemaTypes = FindSchemaTypes();
        // 模式名/模板名 -> 模式名，随模板解析逐步扩充（与 LevelLoader 一致）
        var schemaNamesById = schemaTypes.Keys.ToDictionary(k => k);

        var collected = new List<(string Path, JsonLevel Level)>();
        CollectJsonLevels(levelPath, new HashSet<string>(), collected);

        var templates = new Dictionary<string, string>(); // 模板名 -> 模式名
        var namedEntityIds = new HashSet<string>(); // 所有有名实体的 $id
        var nameReferences = new List<(string Name, string Source)>(); // 语句中对有名实体的引用

        foreach (var (path, level) in collected)
        {
            // 解析模板语句
            foreach (var (key, element) in level.Templates)
            {
                Assert.False(
                    templates.ContainsKey(key),
                    $"模板 \"{key}\" 重复定义（文件：{path}）"
                );

                var (schemaName, baseIds) = ParseStatement(
                    element,
                    schemaNamesById,
                    schemaTypes,
                    $"模板 \"{key}\"（文件：{path}）"
                );
                AssertBaseIdsDefined(baseIds, schemaName, templates, $"模板 \"{key}\"（文件：{path}）");
                CollectNameReferences(element, $"模板 \"{key}\"（文件：{path}）", nameReferences);

                templates[key] = schemaName;
                schemaNamesById[key] = schemaName;
            }

            // 解析实体语句
            for (var i = 0; i < level.Entities.Length; i++)
            {
                var element = level.Entities[i];
                var context = $"第 {i} 个实体（文件：{path}）";

                var (_, baseIds) = ParseStatement(element, schemaNamesById, schemaTypes, context);
                AssertBaseIdsDefined(baseIds, null, templates, context);
                CollectNameReferences(element, context, nameReferences);

                if (
                    element.TryGetProperty("$id", out var idProp)
                    && idProp.ValueKind == JsonValueKind.String
                )
                    namedEntityIds.Add(idProp.GetString()!);
            }

            // 校验 configs 可作为配置源解析
            if (level.Configs is { } configs)
            {
                using var stream = new MemoryStream(
                    System.Text.Encoding.UTF8.GetBytes(configs.GetRawText())
                );
                new ConfigurationBuilder().AddJsonStream(stream).Build();
            }
        }

        // 引用完整性：语句中对有名实体（阵营、父级等）的引用必须能在 $id 集合中解析
        // （对应 WorldLoader 中 translator 通过 namedEntities 解析 Team/Parent 等字段）
        foreach (var (name, source) in nameReferences)
            Assert.Contains(
                name,
                namedEntityIds
            );
    }

    /// <summary>
    /// 复刻 LevelLoader.CollectJsonLevels：递归收集 includes，被包含文件在前
    /// </summary>
    private static void CollectJsonLevels(
        string path,
        HashSet<string> visited,
        List<(string Path, JsonLevel Level)> collected
    )
    {
        if (!visited.Add(path))
            return;

        Assert.True(File.Exists(path), $"关卡（或其 include）文件不存在：{path}");

        JsonLevel level;
        using (var stream = File.OpenRead(path))
        {
            level =
                JsonSerializer.Deserialize<JsonLevel>(stream, BasicOptions)
                ?? throw new JsonException($"关卡文件内容为空：{path}");
        }

        foreach (var include in level.Includes)
            CollectJsonLevels(
                Path.Combine(Path.GetDirectoryName(path)!, include),
                visited,
                collected
            );

        collected.Add((path, level));
    }

    /// <summary>
    /// 复刻 DeclarationStatementJsonConverter.Read 的解析与校验
    /// </summary>
    private static (string SchemaName, string[] BaseIds) ParseStatement(
        JsonElement element,
        Dictionary<string, string> schemaNamesById,
        Dictionary<string, Type> schemaTypes,
        string context
    )
    {
        Assert.True(element.TryGetProperty("$base", out var baseProp), $"语句缺少 \"$base\"：{context}");

        string[] baseIds = baseProp.ValueKind switch
        {
            JsonValueKind.String => [baseProp.GetString()!],
            JsonValueKind.Array => [.. baseProp.EnumerateArray().Select(x => x.GetString()!)],
            _ => throw new Exception($"\"$base\" 必须是字符串或字符串数组：{context}"),
        };
        Assert.NotEmpty(baseIds);

        foreach (var id in baseIds)
            Assert.True(
                schemaNamesById.ContainsKey(id),
                $"\"$base\" 引用的 \"{id}\" 既不是模式名，也不是此前已定义的模板：{context}"
            );

        var schemaName = schemaNamesById[baseIds[0]];
        Assert.True(
            baseIds.All(b => schemaNamesById[b] == schemaName),
            $"一条语句的所有 \"$base\" 必须属于同一模式：{context}"
        );

        // 按声明类型做强类型反序列化，校验各字段的类型与取值可解析
        try
        {
            var declaration = element.Deserialize(schemaTypes[schemaName], StatementOptions);
            Assert.NotNull(declaration);
        }
        catch (JsonException e)
        {
            throw new JsonException($"语句无法按模式 \"{schemaName}\" 反序列化：{context}", e);
        }

        return (schemaName, baseIds);
    }

    private static void AssertBaseIdsDefined(
        string[] baseIds,
        string? schemaName,
        Dictionary<string, string> templates,
        string context
    )
    {
        // 与 WorldLoader 一致：除模式名外，$base 引用的必须是已解析的模板
        foreach (var id in baseIds.Where(b => b != schemaName))
            Assert.True(
                templates.ContainsKey(id),
                $"\"$base\" 引用的模板 \"{id}\" 未在此前定义：{context}"
            );
    }

    /// <summary>
    /// 收集语句中对有名实体的名字引用：team、parent 字段与 ships 字典的键
    /// </summary>
    private static void CollectNameReferences(
        JsonElement element,
        string context,
        List<(string Name, string Source)> references
    )
    {
        foreach (var field in new[] { "team", "parent" })
            if (
                element.TryGetProperty(field, out var prop)
                && prop.ValueKind == JsonValueKind.String
            )
                references.Add((prop.GetString()!, $"{context} 的 \"{field}\""));

        if (
            element.TryGetProperty("ships", out var ships)
            && ships.ValueKind == JsonValueKind.Object
        )
            foreach (var team in ships.EnumerateObject())
                references.Add((team.Name, $"{context} 的 \"ships\" 键"));
    }
}

