using System.Text.Json;

namespace OpenSolarMax.Tests.Data;

/// <summary>
/// manifest.json 的测试侧数据模型，与 Game 内部 ModManifest 一比一对应
/// （ModManifest 是 internal，本次任务不允许改动产品代码，故在测试内镜像一份）
/// </summary>
internal class ManifestModel
{
    public string Type { get; set; } = "";

    public string FullName { get; set; } = "";

    public string ShortName { get; set; } = "";

    public string? Preview { get; set; }

    public string? Background { get; set; }

    public string Author { get; set; } = "";

    public string Version { get; set; } = "";

    public string Description { get; set; } = "";

    public string Link { get; set; } = "";

    public string? Uuid { get; set; }

    public string? Assembly { get; set; }

    public string? Content { get; set; }

    public string? Configs { get; set; }

    public string? Levels { get; set; }

    public ManifestDependencies? Dependencies { get; set; }
}

internal class ManifestDependencies
{
    public string[]? Behaviors { get; set; }

    public string[]? Content { get; set; }
}

/// <summary>
/// 模组清单校验：levels/ 与 src/ 下所有 manifest.json 的字段合法性与依赖引用完整性
/// </summary>
public class ManifestValidationTests
{
    private static readonly JsonSerializerOptions Options = new() { PropertyNameCaseInsensitive = true };

    public static TheoryData<string> AllManifests()
    {
        var data = new TheoryData<string>();

        foreach (var root in new[] { "levels", "src" })
        {
            var dir = Path.Combine(RepoRoot.Path, root);
            foreach (var pack in Directory.EnumerateDirectories(dir))
            {
                var manifest = Path.Combine(pack, "manifest.json");
                if (File.Exists(manifest))
                    data.Add(Path.GetRelativePath(RepoRoot.Path, manifest));
            }
        }

        return data;
    }

    private static (string Dir, ManifestModel Manifest) Load(string relativePath)
    {
        var path = Path.Combine(RepoRoot.Path, relativePath);
        var manifest =
            JsonSerializer.Deserialize<ManifestModel>(File.ReadAllText(path), Options)
            ?? throw new JsonException($"manifest 内容为空：{relativePath}");
        return (Path.GetDirectoryName(path)!, manifest);
    }

    [Theory]
    [MemberData(nameof(AllManifests))]
    public void 清单字段合法(string relativePath)
    {
        var (dir, manifest) = Load(relativePath);

        Assert.Contains(manifest.Type, new[] { "behavior", "content", "levels" });
        Assert.False(string.IsNullOrWhiteSpace(manifest.FullName), $"{relativePath}：缺少 fullName");
        Assert.True(
            System.Version.TryParse(manifest.Version, out _),
            $"{relativePath}：version \"{manifest.Version}\" 不是合法版本号"
        );

        if (manifest.Type == "behavior")
            Assert.False(
                string.IsNullOrWhiteSpace(manifest.Assembly),
                $"{relativePath}：行为模组必须声明 assembly"
            );

        // 清单中显式声明的资源路径必须真实存在
        if (manifest.Preview is not null)
            Assert.True(File.Exists(Path.Combine(dir, manifest.Preview)), $"{relativePath}：preview 不存在");
        if (manifest.Background is not null)
            Assert.True(File.Exists(Path.Combine(dir, manifest.Background)), $"{relativePath}：background 不存在");
        if (manifest.Content is not null)
            Assert.True(Directory.Exists(Path.Combine(dir, manifest.Content)), $"{relativePath}：content 目录不存在");
        if (manifest.Configs is not null)
            Assert.True(File.Exists(Path.Combine(dir, manifest.Configs)), $"{relativePath}：configs 不存在");
        if (manifest.Levels is not null)
            Assert.True(Directory.Exists(Path.Combine(dir, manifest.Levels)), $"{relativePath}：levels 目录不存在");
    }

    [Theory]
    [MemberData(nameof(AllManifests))]
    public void 清单依赖引用完整(string relativePath)
    {
        var (_, manifest) = Load(relativePath);
        if (manifest.Dependencies is null)
            return;

        // 收集仓库内所有已知模组的 fullName（按类型）
        var known = new Dictionary<string, HashSet<string>>
        {
            ["behavior"] = [],
            ["content"] = [],
            ["levels"] = [],
        };
        foreach (var other in AllManifests())
        {
            var (_, m) = Load(other);
            if (known.ContainsKey(m.Type))
                known[m.Type].Add(m.FullName);
        }

        foreach (var dep in manifest.Dependencies.Behaviors ?? [])
            Assert.Contains(dep, known["behavior"]);
        foreach (var dep in manifest.Dependencies.Content ?? [])
            Assert.Contains(dep, known["content"]);
    }

    [Fact]
    public void 清单发现机制正常工作()
    {
        // 至少应有两个关卡包与两个行为模组的清单
        Assert.True(AllManifests().Count >= 4, $"发现的 manifest 数量异常：{AllManifests().Count}");
    }
}

