using System.Text.Json;

namespace OpenSolarMax.Tests.Data;

/// <summary>
/// 内容 JSON 校验：动画剪辑与纹理图集两类数据文件的结构与引用校验
/// </summary>
public class ContentJsonValidationTests
{
    private static readonly JsonSerializerOptions Options = new() { PropertyNameCaseInsensitive = true };

    private static IEnumerable<string> EnumerateContentFiles(params string[] subPaths)
    {
        foreach (var project in Directory.EnumerateDirectories(Path.Combine(RepoRoot.Path, "src")))
        {
            foreach (var sub in subPaths)
            {
                var dir = Path.Combine(project, "Content", sub);
                if (!Directory.Exists(dir))
                    continue;

                foreach (var file in Directory.EnumerateFiles(dir, "*.json", SearchOption.AllDirectories))
                    yield return Path.GetRelativePath(RepoRoot.Path, file);
            }
        }
    }

    public static TheoryData<string> AnimationFiles() => [.. EnumerateContentFiles("Animations")];

    public static TheoryData<string> AtlasFiles() =>
        [.. EnumerateContentFiles("Textures", "UIs")];

    [Theory]
    [MemberData(nameof(AnimationFiles))]
    public void 动画剪辑结构合法(string relativePath)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(RepoRoot.Path, relativePath)));
        var root = doc.RootElement;

        Assert.Equal(JsonValueKind.Object, root.ValueKind);
        Assert.True(
            root.TryGetProperty("duration", out var duration)
                && duration.ValueKind == JsonValueKind.Number
                && duration.GetDouble() >= 0,
            $"{relativePath}：缺少合法的 duration"
        );
        Assert.True(
            root.TryGetProperty("curves", out var curves) && curves.ValueKind == JsonValueKind.Object,
            $"{relativePath}：缺少 curves"
        );

        foreach (var curve in curves.EnumerateObject())
        {
            Assert.True(
                curve.Value.ValueKind == JsonValueKind.Array && curve.Value.GetArrayLength() > 0,
                $"{relativePath}：曲线 \"{curve.Name}\" 必须是非空数组"
            );

            foreach (var keyframe in curve.Value.EnumerateArray())
                Assert.True(
                    keyframe.ValueKind == JsonValueKind.Object
                        && keyframe.TryGetProperty("time", out var time)
                        && time.ValueKind == JsonValueKind.Number,
                    $"{relativePath}：曲线 \"{curve.Name}\" 存在缺少数值 time 的关键帧"
                );
        }
    }

    [Theory]
    [MemberData(nameof(AtlasFiles))]
    public void 纹理图集结构合法(string relativePath)
    {
        var dir = Path.GetDirectoryName(Path.Combine(RepoRoot.Path, relativePath))!;
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(RepoRoot.Path, relativePath)));
        var root = doc.RootElement;

        Assert.Equal(JsonValueKind.Object, root.ValueKind);
        Assert.True(
            root.TryGetProperty("image", out var image) && image.ValueKind == JsonValueKind.String,
            $"{relativePath}：缺少 image"
        );
