    /// 用真实的 LevelLoader 加载一个关卡文件（含其递归 includes），失败时抛出产品代码自身的异常
    /// </summary>
    public static LevelFile Load(string levelPath)
    {
        var loader = new LevelLoader(FindSchemaInfos());
        using var fs = new PhysicalFileSystem();
        // LevelLoader.Load 的 assets 参数在当前实现中未被使用
        return loader.Load(fs, null!, fs.ConvertPathFromInternal(levelPath));
    }

    public static void Validate(string levelPath)
    {
        var level = Load(levelPath);

        // 所有有名实体的 $id
        var namedIds = level
            .Entities.Where(e => e.Id is not null)
            .Select(e => e.Id!)
            .ToHashSet();

        // 收集全部语句中对有名实体的名字引用
        var references = new List<(string Name, string Source)>();
        foreach (var (key, statement) in level.Templates)
            CollectNameReferences(statement.Declaration, $"模板 \"{key}\"", references);
        foreach (var (id, statement) in level.Entities)
            CollectNameReferences(
                statement.Declaration,
                $"实体 \"{id ?? "(无名)"}\"（模式 {statement.SchemaName}）",
                references
            );

        foreach (var (name, source) in references)
            Assert.True(
                namedIds.Contains(name),
                $"引用的有名实体 \"{name}\" 不存在（没有任何实体以 \"$id\": \"{name}\" 声明）：{source}"
            );
    }

    /// <summary>
    /// 从强类型的声明对象中收集名字引用：Team/Parent 字符串字段与 Ships 字典的键
    /// </summary>
    private static void CollectNameReferences(
        IDeclaration declaration,
        string source,
        List<(string Name, string Source)> references
    )
    {
        foreach (
            var property in declaration.GetType().GetProperties(BindingFlags.Public | BindingFlags.Instance)
        )
        {
            if (
                property.PropertyType == typeof(string)
                && property.Name is "Team" or "Parent"
                && property.GetValue(declaration) is string name
            )
                references.Add((name, $"{source} 的 {property.Name}"));

            if (
                property.PropertyType == typeof(OneOf<int, Dictionary<string, int>>)
                && property.GetValue(declaration) is OneOf<int, Dictionary<string, int>> ships
                && ships.TryPickT1(out var teams, out _)
            )
                foreach (var team in teams.Keys)
                    references.Add((team, $"{source} 的 {property.Name} 键"));
        }
    }
}

