using System.Text.Json;
using System.Text.Json.Serialization;
using OpenSolarMax.Game.Modding;

namespace OpenSolarMax.Tests.Data;

/// <summary>
/// 模组清单校验：levels/ 与 src/ 下所有 manifest.json，
/// 使用真实的 ModManifest 类型（经 Game 工程 InternalsVisibleTo 访问）反序列化，
/// 校验字段合法性与依赖引用完整性
/// </summary>
public class ManifestValidationTests
{
    /// <summary>
    /// 与 ModsManager.ManifestJsonOptions 一致（该字段为 private，测试侧按相同配置构造）
    /// </summary>
    private static readonly JsonSerializerOptions Options = new()
    {
        PropertyNameCaseInsensitive = true,
        IncludeFields = true,
        Converters = { new JsonStringEnumConverter() },
    };

    public static TheoryData<string> AllManifests()
    {
        var data = new TheoryData<string>();

        foreach (var root in new[] { "levels", "src" })
        {
            var dir = Path.Combine(RepoRoot.Path, root);
            foreach (var pack in Directory.EnumerateDirectories(dir))
            {
                var manifest = Path.Combine(pack, "manifest.json");
                if (File.Exists(manifest))
                    data.Add(Path.GetRelativePath(RepoRoot.Path, manifest));
            }
        }

        return data;
    }

    private static (string Dir, ModManifest Manifest) Load(string relativePath)
    {
        var path = Path.Combine(RepoRoot.Path, relativePath);
        using var stream = File.OpenRead(path);
        try
        {
            var manifest =
                JsonSerializer.Deserialize<ModManifest>(stream, Options)
                ?? throw new JsonException("manifest 内容为空");
            return (Path.GetDirectoryName(path)!, manifest);
        }
        catch (JsonException e)
        {
            throw new JsonException($"manifest 无法按 ModManifest 类型解析：{relativePath}", e);
        }
    }

    [Theory]
    [MemberData(nameof(AllManifests))]
    public void 清单字段合法(string relativePath)
    {
        var (dir, manifest) = Load(relativePath);

        // type 非法时反序列化已直接抛异常，此处校验其余字段
        Assert.False(string.IsNullOrWhiteSpace(manifest.FullName), $"{relativePath}：缺少 fullName");
        Assert.True(
            Version.TryParse(manifest.Version, out _),
            $"{relativePath}：version \"{manifest.Version}\" 不是合法版本号"
        );

        if (manifest.Type == ModType.Behavior)
            Assert.False(
                string.IsNullOrWhiteSpace(manifest.Assembly),
                $"{relativePath}：行为模组必须声明 assembly"
            );

        // 清单中显式声明的资源路径必须真实存在（未声明时由 ModsManager 按默认模式查找）
        if (manifest.Preview is not null)
            Assert.True(
                File.Exists(Path.Combine(dir, manifest.Preview)),
                $"{relativePath}：preview 不存在"
            );
        if (manifest.Background is not null)
            Assert.True(
                File.Exists(Path.Combine(dir, manifest.Background)),
                $"{relativePath}：background 不存在"
            );
        if (manifest.Content is not null)
            Assert.True(
                Directory.Exists(Path.Combine(dir, manifest.Content)),
                $"{relativePath}：content 目录不存在"
            );
        if (manifest.Configs is not null)
            Assert.True(
                File.Exists(Path.Combine(dir, manifest.Configs)),
                $"{relativePath}：configs 不存在"
            );
        if (manifest.Levels is not null)
            Assert.True(
                Directory.Exists(Path.Combine(dir, manifest.Levels)),
                $"{relativePath}：levels 目录不存在"
            );
    }

    [Theory]
    [MemberData(nameof(AllManifests))]
    public void 清单依赖引用完整(string relativePath)
    {
        var (_, manifest) = Load(relativePath);
        if (manifest.Dependencies is null)
            return;

        // 收集仓库内所有已知模组的 fullName（按类型）
        var known = new Dictionary<ModType, HashSet<string>>
        {
            [ModType.Behavior] = [],
            [ModType.Content] = [],
            [ModType.Levels] = [],
        };
        foreach (var other in AllManifests())
            known[Load(other).Manifest.Type].Add(Load(other).Manifest.FullName);

        foreach (var dep in manifest.Dependencies.Behaviors ?? [])
            Assert.Contains(dep, known[ModType.Behavior]);
        foreach (var dep in manifest.Dependencies.Content ?? [])
            Assert.Contains(dep, known[ModType.Content]);
    }

    [Fact]
    public void 清单发现机制正常工作()
    {
        // 至少应有两个关卡包与两个行为模组的清单
        Assert.True(AllManifests().Count >= 4, $"发现的 manifest 数量异常：{AllManifests().Count}");
    }
}

