using System.Collections.Concurrent;
using System.Runtime.ExceptionServices;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;

namespace OpenSolarMax.Tests.Common;

/// <summary>
/// 进程级共享的图形设备夹具。
/// </summary>
/// <remarks>
/// <para>
/// 创建方式沿用阶段 0 验证结论：<see cref="Game"/> +
/// <see cref="GraphicsDeviceManager.ApplyChanges"/>（不调用 Run，窗口保持隐藏）。
/// 直接构造 <c>GraphicsDevice</c> 的路径在 DesktopGL 下不可用（MonoGame issue #5089）。
/// </para>
/// <para>
/// 线程模型照 MonoGame 官方测试的做法：GL 上下文绑定创建线程，
/// 所有 MonoGame 对象的创建与操作都编组到夹具自有的专用线程上执行。
/// 调用方通过 <see cref="Run(Action)"/> / <see cref="Run{T}(Func{T})"/> 提交工作。
/// </para>
/// <para>
/// 编组只保证线程亲和，不隔离设备状态（如当前 RenderTarget）。
/// 使用本夹具的测试工程应关闭用例并行，避免多个用例的操作在专用线程上交错。
/// </para>
/// <para>
/// 消费方注册方式：<c>[assembly: AssemblyFixture(typeof(GraphicsDeviceFixture))]</c>，
/// 或在测试类上实现 <c>IAssemblyFixture&lt;GraphicsDeviceFixture&gt;</c>。
/// </para>
/// </remarks>
public sealed class GraphicsDeviceFixture : IDisposable
{
    private readonly Game _game = new HostGame();
    private readonly BlockingCollection<Action> _workQueue = new(new ConcurrentQueue<Action>());
    private readonly ManualResetEventSlim _initialized = new(false);
    private readonly Thread _thread;
    private Exception? _initializationFailure;

    public GraphicsDeviceFixture()
    {
        _thread = new Thread(RunLoop) { Name = "GraphicsDeviceFixture", IsBackground = true };
        _thread.Start();
        _initialized.Wait();

        if (_initializationFailure is not null)
        {
            _workQueue.CompleteAdding();
            throw new InvalidOperationException(
                "GraphicsDevice 创建失败。请检查图形环境：有桌面会话时应可直接创建；"
                    + "无桌面会话的环境需要 /dev/dri 可用（KMSDRM/offscreen），否则用 xvfb-run 启动测试。",
                _initializationFailure
            );
        }

        GraphicsDevice = _graphicsDevice!;
    }

    /// <summary>共享的图形设备。只能在 <see cref="Run(Action)"/> 提交的工作中安全使用。</summary>
    public GraphicsDevice GraphicsDevice { get; }

    private GraphicsDevice? _graphicsDevice;

    /// <summary>在夹具专用线程上执行 <paramref name="action"/> 并等待完成，异常原样抛回调用方。</summary>
    public void Run(Action action)
    {
        ExceptionDispatchInfo? failure = null;
        using var done = new ManualResetEventSlim();
        _workQueue.Add(() =>
        {
            try
            {
                action();
            }
            catch (Exception ex)
            {
                failure = ExceptionDispatchInfo.Capture(ex);
            }
            finally
            {
                done.Set();
            }
        });
        done.Wait();
        failure?.Throw();
    }

    /// <summary>在夹具专用线程上执行 <paramref name="func"/> 并返回结果，异常原样抛回调用方。</summary>
    public T Run<T>(Func<T> func)
    {
        T result = default!;
        Run(() => result = func());
        return result;
    }

    private void RunLoop()
    {
        try
        {
            // 全部 MonoGame 对象都在本线程创建，保证 GL 上下文线程亲和
            var gdm = new GraphicsDeviceManager(_game) { GraphicsProfile = GraphicsProfile.HiDef };
            gdm.ApplyChanges();
            _graphicsDevice = gdm.GraphicsDevice;
        }
        catch (Exception ex)
        {
            _initializationFailure = ex;
        }
        finally
        {
            _initialized.Set();
        }

        foreach (var work in _workQueue.GetConsumingEnumerable())
        {
            work(); // 异常已在 Run 内捕获，此处不会抛出
        }

        // Game.Dispose 会一并清理 GraphicsDeviceManager 与 GraphicsDevice
        _game.Dispose();
    }

    public void Dispose()
    {
        _workQueue.CompleteAdding();
        _thread.Join();
        _workQueue.Dispose();
        _initialized.Dispose();
    }

    /// <summary>仅为满足 MonoGame 对 Game 实例的要求（SdlGameWindow.Instance），不启动游戏循环。</summary>
    private sealed class HostGame : Game;
}

using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using OpenSolarMax.Tests.Common;

Console.WriteLine($"构造夹具（当前线程 {Environment.CurrentManagedThreadId}）");
using var fixture = new GraphicsDeviceFixture();
Console.WriteLine($"  设备就绪, Viewport={fixture.GraphicsDevice.Viewport.Bounds}");

Console.WriteLine("跨线程 Run：Texture2D 写入/读回");
var color = fixture.Run(() =>
{
    Console.WriteLine($"  工作线程 {Environment.CurrentManagedThreadId}");
    var tex = new Texture2D(fixture.GraphicsDevice, 4, 4);
    var data = new Color[16];
    for (var i = 0; i < 16; i++)
        data[i] = new Color(i * 16, 0, 0);
    tex.SetData(data);
    var readBack = new Color[16];
    tex.GetData(readBack);
    tex.Dispose();
    return readBack[1];
});
Console.WriteLine($"  readBack[1]={color}（期望 R=16 G=0 B=0）");

Console.WriteLine("跨线程 Run：RenderTarget2D + Clear + 读回");
var rtPixel = fixture.Run(() =>
{
    var device = fixture.GraphicsDevice;
    var rt = new RenderTarget2D(device, 64, 64);
    device.SetRenderTarget(rt);
    device.Clear(Color.CornflowerBlue);
    var data = new Color[64 * 64];
    rt.GetData(data);
    device.SetRenderTarget(null);
    rt.Dispose();
    return data[0];
});
Console.WriteLine($"  RT[0]={rtPixel}（期望 R=100 G=149 B=237）");

Console.WriteLine("跨线程 Run：异常应原样抛回");
try
{
    fixture.Run(() => throw new InvalidOperationException("探针异常"));
    Console.WriteLine("  失败：未抛出");
}
catch (InvalidOperationException ex) when (ex.Message == "探针异常")
{
    Console.WriteLine("  异常原样抛回，堆栈保留: " + ex.StackTrace!.Split('\n')[0].Trim());
}

Console.WriteLine("并发提交 8 个 Run（验证队列串行化）");
var tasks = Enumerable
    .Range(0, 8)
    .Select(i => Task.Run(() => fixture.Run(() => Thread.Sleep(50))))
    .ToArray();
Task.WaitAll(tasks);
Console.WriteLine("  全部完成");

Console.WriteLine("释放");
Console.WriteLine("全部通过");

