61:         _localAssets = localAssets;
62:         _localConfigs = localConfigs;
63:         _game = game;
64: 
65:         _levelLoader = new LevelLoader(declarationSchemaInfos);
66: 
67:         _gameplayBranch = BuildBranch(gameplayBehaviors);
68:         _previewBranch = BuildBranch(previewBehaviors);
69: 
70:         _levels = metadata
71:             .Levels.EnumerateFiles("*.json")
72:             .Where(f => !f.Name.StartsWith('.'))
73:             .Select(f => new LevelInfo(f.NameWithoutExtension, f))
74:             .ToList();
75:     }
76: 
77:     public IReadOnlyList<LevelInfo> Levels => _levels;
78: 
79:     // TODO: 游玩关卡理想上应缓存（关卡数据或已构建的世界），实际进入时再拷贝一份，
80:     // 以免两次进入的状态互相续上；当前没有拷贝机制，故每次重新读取并构建。
81:     public LevelSession LoadLevel(LevelInfo entry) => LoadLevelCore(entry, _gameplayBranch, true);
82: 
83:     public Lifetime<LevelSession> LoadLevelPreview(LevelInfo entry)
84:     {
85:         // 预览走 scoped LRU：淘汰只减缓存那份计数，持有 Lifetime 的预览不会被释放
86:         return _previewCache.ScopedGetOrAdd(
87:             entry,
88:             key => new Scoped<LevelSession>(LoadLevelCore(key, _previewBranch, false))
89:         );
90:     }
91: 
92:     private BehaviorBranch BuildBranch(BakedBehaviorsInfo behaviors)
93:     {
94:         var factory = new ConceptFactory(
95:             behaviors.ConceptInfos.Values,
96:             new Dictionary<Type, object>
97:             {
98:                 [typeof(GraphicsDevice)] = _game.GraphicsDevice,
99:                 [typeof(IAssetsManager)] = _localAssets,
100:                 [typeof(IConfigurationRoot)] = _localConfigs,
101:             }
102:         );
103:         var translators = new TranslatorsRegistry(behaviors.TranslatorTypes);
104:         return new BehaviorBranch(behaviors, factory, new WorldLoader(factory, translators));
105:     }
106: 
107:     private LevelSession LoadLevelCore(LevelInfo entry, BehaviorBranch branch, bool injectFmod)
108:     {
109:         // 重新解析关卡文件（不缓存）
110:         var level = _levelLoader.Load(entry.File.FileSystem, _localAssets, entry.File.Path);
111: 
112:         // 构造关卡级配置（叠加到模组 LocalConfigs 之上）
113:         IConfigurationRoot effectiveConfigs;
114:         if (level.Configs is { } levelConfigs)
115:         {
116:             effectiveConfigs = new ConfigurationBuilder()
117:                 .AddConfiguration(_localConfigs)
118:                 .AddConfiguration(levelConfigs)
119:                 .Build();
120:         }
121:         else
122:         {
123:             effectiveConfigs = _localConfigs;
124:         }
125: 
126:         var behaviors = branch.Behaviors;
127: 
128:         // 构造世界和四大系统
129:         var world = World.Create();
130:         var inputSystem = new AggregateSystem(
131:             world,
132:             behaviors.SystemTypes.Input,
133:             new Dictionary<Type, object>
134:             {
135:                 [typeof(IAssetsManager)] = _localAssets,
136:                 [typeof(IConceptFactory)] = branch.Factory,
137:                 [typeof(IConfigurationRoot)] = effectiveConfigs,
138:             },
139:             behaviors.HookImplMethods.ToDictionary(
140:                 kv => kv.Key,
141:                 kv => kv.Value as IReadOnlyList<MethodInfo>
142:             )
143:         );
144:         var aiSystem = new AggregateSystem(
145:             world,
146:             behaviors.SystemTypes.Ai,
147:             new Dictionary<Type, object>
148:             {
149:                 [typeof(IAssetsManager)] = _localAssets,
150:                 [typeof(IConceptFactory)] = branch.Factory,
151:                 [typeof(IConfigurationRoot)] = effectiveConfigs,
152:             },
153:             behaviors.HookImplMethods.ToDictionary(
154:                 kv => kv.Key,
155:                 kv => kv.Value as IReadOnlyList<MethodInfo>
156:             )
157:         );
158:         var simulateSystem = new AggregateSystem(
159:             world,
160:             behaviors.SystemTypes.Simulate,
161:             new Dictionary<Type, object>
162:             {
163:                 [typeof(IAssetsManager)] = _localAssets,
164:                 [typeof(IConceptFactory)] = branch.Factory,
165:                 [typeof(IConfigurationRoot)] = effectiveConfigs,
166:             },
167:             behaviors.HookImplMethods.ToDictionary(
168:                 kv => kv.Key,
169:                 kv => kv.Value as IReadOnlyList<MethodInfo>
170:             )
171:         );
172:         var renderSystem = new AggregateSystem(
173:             world,
174:             behaviors.SystemTypes.Render,
175:             new Dictionary<Type, object>
176:             {
177:                 [typeof(GraphicsDevice)] = _game.GraphicsDevice,
178:                 [typeof(IAssetsManager)] = _localAssets,
179:                 [typeof(IConfigurationRoot)] = effectiveConfigs,
180:             },
181:             behaviors.HookImplMethods.ToDictionary(
182:                 kv => kv.Key,
183:                 kv => kv.Value as IReadOnlyList<MethodInfo>
184:             )
185:         );
186: 
187:         // 加载关卡内容
188:         var commandBuffer = new CommandBuffer();
189:         var enumerator = branch.WorldLoader.LoadStepByStep(level, world, commandBuffer);
190:         while (enumerator.MoveNext())
191:         {
192:             commandBuffer.Playback(world);
193:             simulateSystem.LateUpdate();
194:         }
195: 
196:         // 仅游戏阶段注入 FMOD 系统
197:         if (injectFmod)
198:         {
199:             world.Query(
200:                 new QueryDescription().WithAll<FMOD.Studio.System>(),
201:                 (ref FMOD.Studio.System fmodSystem) => fmodSystem = _game.FmodSystem
202:             );
203:         }
204: 
205:         // 返回结果
206:         return new LevelSession(world, inputSystem, aiSystem, simulateSystem, renderSystem);
207:     }
208: 
209:     public void Dispose()
210:     {
211:         // 先释放缓存中剩余的预览，再释放 LocalAssets
212:         foreach (var (_, scoped) in _previewCache)
213:             scoped.Dispose();
214: 
215:         _localAssets.Dispose();
216:         foreach (var mod in _behaviorMods)
217:             mod.Dispose();
218:         foreach (var mod in _contentMods)
219:             mod.Dispose();
220:     }
221: }

