250:                 _scrollViewer.Widgets.RemoveAt(e.OldStartingIndex);
251:                 break;
252:             case NotifyCollectionChangedAction.Replace:
253:                 _scrollViewer.Widgets[e.NewStartingIndex] = GenerateLabel((string)e.NewItems?[0]!);
254:                 break;
255:             case NotifyCollectionChangedAction.Move:
256:                 _scrollViewer.Widgets.Move(e.OldStartingIndex, e.NewStartingIndex);
257:                 break;
258:             case NotifyCollectionChangedAction.Reset:
259:                 _scrollViewer.Widgets.Clear();
260:                 foreach (var name in ViewModel.Items)
261:                     _scrollViewer.Widgets.Add(GenerateLabel(name));
262:                 break;
263:             default:
