268:     private void ScrollViewerOnThumbnailsPositionChanged(object? sender, EventArgs e)
269:     {
270:         var primaryOnly =
271:             _scrollViewer.Offset == 0
272:             || (_scrollViewer.NearestIndex == 0 && _scrollViewer.Offset < 0)
273:             || (
274:                 _scrollViewer.NearestIndex == _scrollViewer.Widgets.Count - 1
275:                 && _scrollViewer.Offset > 0
276:             );
277: 
278:         ViewModel.PrimaryItemIndex = _scrollViewer.NearestIndex;
279:         ViewModel.SecondaryItemIndex = primaryOnly
280:             ? null
281:             : _scrollViewer.NearestIndex + int.Sign(_scrollViewer.Offset);
282: 
283:         _primaryPreview.FadeIn = MathF.Max(
284:             1 - int.Abs(_scrollViewer.Offset) / (_scrollViewer.ThumbnailsInterval / 2f),
285:             0
286:         );
287:         _secondaryPreview.FadeIn = MathF.Max(
288:             1
289:                 - (_scrollViewer.ThumbnailsInterval - int.Abs(_scrollViewer.Offset))
290:                     / (_scrollViewer.ThumbnailsInterval / 2f),
291:             0
292:         );
293:         _secondaryPreview.Visible = !primaryOnly;
294: 
295:         // 永远保持 secondary 背景在下
296:         if (_primaryBackground.Texture is not null)
297:         {
298:             _primaryBackground.Alpha =
299:                 MathF.Max(1 - float.Abs(_scrollViewer.Offset) / _scrollViewer.ThumbnailsInterval, 0)
300:                 * _commonBackgroundAlpha;
301:             _secondaryBackground.Alpha = 1 * _commonBackgroundAlpha;
302:         }
303:         else
304:         {
305:             _secondaryBackground.Alpha =
306:                 MathF.Max(float.Abs(_scrollViewer.Offset) / _scrollViewer.ThumbnailsInterval, 0)
307:                 * _commonBackgroundAlpha;
308:         }
