204:     private static Dictionary<string, ConceptRelatedTypes> FindConceptRelatedTypes(
205:         Assembly assembly,
206:         GameplayOrPreview scene
207:     )
208:     {
209:         var definitionTypes = new Dictionary<string, Type>();
210:         var descriptionTypes = new Dictionary<string, Type>();
211:         var applierTypes = new Dictionary<string, Type>();
212:         foreach (var type in assembly.GetExportedTypes())
213:         {
214:             // 筛选符合场景要求的概念类型
215:             if ((GetBehaviorTypeScene(type) & scene) == 0)
216:                 continue;
217: 
218:             if (type.GetInterfaces().Contains(typeof(IDefinition)))
219:             {
220:                 var name = type.GetCustomAttribute<DefineAttribute>()!.Key;
221:                 definitionTypes.Add(name, type);
222:             }
223:             else if (type.GetInterfaces().Contains(typeof(IDescription)))
224:             {
225:                 var name = type.GetCustomAttribute<DescribeAttribute>()!.Key;
226:                 descriptionTypes.Add(name, type);
227:             }
228:             else if (
229:                 type.GetInterfaces().Contains(typeof(IApplier))
230:                 || type.GetInterfaces()
231:                     .Any(i => i.IsGenericType && i.GetGenericTypeDefinition() == typeof(IApplier<>))
232:             )
233:             {
234:                 var name = type.GetCustomAttribute<ApplyAttribute>()!.Key;
235:                 applierTypes.Add(name, type);
236:             }
237:         }
238: 
239:         var allConceptNames = definitionTypes
240:             .Keys.Concat(descriptionTypes.Keys)
241:             .Concat(applierTypes.Keys)
242:             .ToHashSet();
243:         return allConceptNames.ToDictionary(
244:             k => k,
245:             k => new ConceptRelatedTypes(
246:                 definitionTypes.TryGetValue(k, out var d) ? d : null,
247:                 descriptionTypes.GetValueOrDefault(k),
248:                 applierTypes.TryGetValue(k, out var a) ? a : null
249:             )
250:         );
251:     }
