259:     private static ImmutableSystemTypeCollection FindSystemTypes(
260:         Assembly assembly,
261:         GameplayOrPreview scene
262:     )
263:     {
264:         var systemTypes = new SystemTypeCollection();
265: 
266:         foreach (var type in assembly.GetExportedTypes())
267:         {
268:             // 排除抽象类、接口、泛型类
269:             if (type.IsAbstract || type.IsInterface || type.ContainsGenericParameters)
270:                 continue;
271: 
272:             // 筛选系统类型
273:             if (
274:                 !type.GetInterfaces()
275:                     .Intersect([
276:                         typeof(ITickSystem),
277:                         typeof(ICalcSystem),
278:                         typeof(IDelayedCalcSystem),
279:                         typeof(IReactiveSystem),
280:                     ])
281:                     .Any()
282:             )
283:                 continue;
284: 
285:             // 排除禁用的系统
286:             if (type.GetCustomAttribute<DisableAttribute>() is not null)
287:                 continue;
288: 
289:             // 筛选符合场景要求的系统
290:             if ((GetBehaviorTypeScene(type) & scene) == 0)
291:                 continue;
292: 
293:             if (type.GetCustomAttribute<SimulateSystemAttribute>() is not null)
294:                 systemTypes.Simulate.Add(type);
295: 
296:             if (type.GetCustomAttribute<InputSystemAttribute>() is not null)
297:                 systemTypes.Input.Add(type);
298: 
299:             if (type.GetCustomAttribute<AiSystemAttribute>() is not null)
300:                 systemTypes.Ai.Add(type);
301: 
302:             if (type.GetCustomAttribute<RenderSystemAttribute>() is not null)
303:                 systemTypes.Render.Add(type);
304:         }
305: 
306:         return systemTypes.ToImmutableSystemTypeCollection();
307:     }
