44:         {
45:             PropertyNameCaseInsensitive = true,
46:             IncludeFields = true,
47:         };
48:         var jsonLevel =
49:             JsonSerializer.Deserialize<JsonLevel>(stream, basicSerializerOptions)
50:             ?? throw new JsonException();
51: 
52:         // 先处理被包含的文件，使其模板和实体位于当前文件内容之前
53:         foreach (var includePath in jsonLevel.Includes)
54:         {
55:             CollectJsonLevels(
