66:     private LevelFile ParseAndMerge(List<(UPath Path, JsonLevel Level)> collected)
67:     {
68:         // 初始化从配置模式索引到配置模式名称的映射
69:         var schemaNamesByDeclarationId = declarationSchemaInfos.Keys.ToDictionary(key => key);
70: 
71:         var statementSerializerOptions = new JsonSerializerOptions()
72:         {
73:             PropertyNameCaseInsensitive = true,
74:             IncludeFields = true,
75:         };
76:         // 添加基础类型转换器
77:         statementSerializerOptions.Converters.Add(new JsonStringEnumConverter());
78:         statementSerializerOptions.Converters.Add(new Vector2JsonConverter());
79:         statementSerializerOptions.Converters.Add(new ColorJsonConverter());
80:         statementSerializerOptions.Converters.Add(new BlendStateJsonConverter());
81:         // 添加 OneOf 转换器
82:         statementSerializerOptions.Converters.Add(new OneOfJsonConverterFactory());
83:         // 添加语句转换器
84:         statementSerializerOptions.Converters.Add(
85:             new DeclarationStatementJsonConverter(
86:                 schemaNamesByDeclarationId,
87:                 declarationSchemaInfos
88:             )
89:         );
