131:             foreach (var system in _lateUpdate1Systems)
132:             {
133:                 if (system is IDelayedCalcSystem delayedCalc)
134:                     delayedCalc.Update(CurrentCommandBuffer);
135:                 else if (system is ICalcSystem calc)
136:                     calc.Update();
137:             }
138: 
139:             // 若本轮没有任何系统缓存延迟操作，则不动点迭代收敛，退出循环
140:             if (_buffers[_currentIndex].Size == 0)
141:                 break;
142: 
143:             // 内循环：反复 Playback 直到 Buffered 排空（上限 32 次执行）
144:             for (var playbackIteration = 0; _buffers[_currentIndex].Size > 0; playbackIteration++)
145:             {
146:                 // 如果迭代次数太多，则抛异常
147:                 if (playbackIteration >= MaxFixpointIterations)
148:                     throw new Exception(
149:                         $"fixpoint did not converge within {MaxFixpointIterations} iterations"
150:                     );
151: 
152:                 // 切换当前写入目标：播放期间回调写入另一个 buffer
153:                 // （_currentIndex 在 0/1 间切换，^ 1 即取另一个 buffer）
154:                 _currentIndex ^= 1;
155:                 _buffers[_currentIndex ^ 1].Playback(_world, dispose: true);
156:             }
157: 
158:             // 退出时两个 buffer 必空
159:             Debug.Assert(_buffers.All(b => b.Size == 0));
160:         }
161: 
162:         Debug.Assert(_buffers.All(b => b.Size == 0));
163: 
164:         // 执行 LateUpdate2 阶段系统
165:         foreach (var system in _lateUpdate2Systems)
166:             system.Update();
167: 
168:         Debug.Assert(_buffers.All(b => b.Size == 0));
169:     }
