8: 
9: internal record BakedBehaviorsInfo(
10:     ImmutableDictionary<string, DeclarationTranslatorInfo> TranslatorTypes,
11:     ImmutableDictionary<string, ConceptInfo> ConceptInfos,
12:     StageSystemTypesCollection SystemTypes,
13:     ImmutableDictionary<string, ImmutableArray<MethodInfo>> HookImplMethods
14: )
15: {
16:     public static BakedBehaviorsInfo Bake(params BehaviorsInfo[] layers)
17:     {
18:         // 合并声明翻译器
19:         var mergedTranslatorTypes = layers
20:             .SelectMany(l => l.DeclarationTranslatorTypes)
21:             .ToImmutableDictionary();
22: 
23:         // 合并概念
24:         var conceptInfos = new Dictionary<string, ConceptInfo>();
25:         foreach (var layer in layers)
26:         {
27:             foreach (var (key, relatedTypes) in layer.ConceptTypes)
28:             {
29:                 if (conceptInfos.TryGetValue(key, out var conceptInfo))
30:                 {
31:                     if (relatedTypes.Description is not null)
32:                         throw new Exception("Concept description cannot be extended!");
33:                     var extendedConcept = conceptInfo.Extend(
34:                         relatedTypes.Definition,
35:                         relatedTypes.Applier
36:                     );
37:                     conceptInfos[key] = extendedConcept;
38:                 }
39:                 else
40:                 {
41:                     if (relatedTypes.Definition is null)
42:                         throw new Exception("A new concept must be provided a definition!");
43:                     var newConcept = ConceptInfo.Define(
44:                         key,
45:                         relatedTypes.Definition,
46:                         relatedTypes.Description,
47:                         relatedTypes.Applier
48:                     );
49:                     conceptInfos.Add(key, newConcept);
50:                 }
51:             }
52:         }
53:         var mergedConceptInfos = conceptInfos.ToImmutableDictionary();
54: 
55:         // 合并系统类型。合并后完成拓扑排序
56:         var mergedSystemTypes = new StageSystemTypesCollection(
57:             Input: SystemsTopology.BakeSortedSystemTypes(
58:                 layers.SelectMany(l => l.SystemTypes.Input).ToImmutableHashSet()
59:             ),
60:             Ai: SystemsTopology.BakeSortedSystemTypes(
61:                 layers.SelectMany(l => l.SystemTypes.Ai).ToImmutableHashSet()
62:             ),
63:             Simulate: SystemsTopology.BakeSortedSystemTypes(
64:                 layers.SelectMany(l => l.SystemTypes.Simulate).ToImmutableHashSet()
65:             ),
66:             Render: SystemsTopology.BakeSortedSystemTypes(
67:                 layers.SelectMany(l => l.SystemTypes.Render).ToImmutableHashSet()
68:             )
69:         );
70: 
71:         // 合并钩子函数
72:         var mergedImplMethods = layers
73:             .SelectMany(l => l.HookImplMethods)
74:             .SelectMany(kv => kv.Value, (kv, i) => (kv.Key, Info: i))
75:             .GroupBy(p => p.Key)
76:             .ToImmutableDictionary(g => g.Key, g => g.Select(p => p.Info).ToImmutableArray());
77: 
78:         return new BakedBehaviorsInfo(
79:             mergedTranslatorTypes,
80:             mergedConceptInfos,
81:             mergedSystemTypes,
82:             mergedImplMethods
83:         );
